package com.tahsin.app.data.quran

import android.content.Context
import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase

/**
 * Read-only Quran text, shipped prebuilt in `assets/databases/quran.db`.
 *
 * Words are not stored: they are derived from `text_uthmani` by
 * [com.tahsin.app.domain.text.ArabicNormalizer], so the display form and the
 * comparison form can never drift out of index-alignment.
 *
 * The asset is generated by `scripts/import_quran.py`, which reads this
 * database's exported schema (`app/schemas/.../1.json`) and writes the matching
 * DDL, `PRAGMA user_version` and `room_master_table` identity hash. Room rejects
 * a prepackaged file that disagrees with the generated code on any of those, so
 * `exportSchema` must stay on and the script must be re-run after any change to
 * the entities here.
 */
@Database(
    entities = [SurahEntity::class, AyahEntity::class],
    version = QuranDatabase.VERSION,
    exportSchema = true,
)
abstract class QuranDatabase : RoomDatabase() {
    abstract fun quranDao(): QuranDao

    companion object {
        const val VERSION = 2
        private const val DB_NAME = "quran.db"
        private const val ASSET_PATH = "databases/quran.db"

        fun create(context: Context): QuranDatabase =
            Room.databaseBuilder(context, QuranDatabase::class.java, DB_NAME)
                .createFromAsset(ASSET_PATH)
                // The text is read-only and always rebuilt from the asset, so any
                // version change just swaps in the new prepackaged file.
                .fallbackToDestructiveMigration()
                .build()
    }
}
